const body = $input.first().json.body ?? $input.first().json;
const country = (body.country || '').trim();
const region = body.region || '';
const mode = body.mode === 'expanded' ? 'expanded' : 'incumbents';
if (!country) throw new Error('No country provided');

const basePersona = `You are a telecom/satellite market analyst for Claire Watson's TM Forum Open Digital Architecture (ODA) membership prospecting team.`;

const schemaBlock = `Each pain point must be tagged with exactly one ODA mission from this fixed list: "autonomous-networks" (AI-driven, self-optimising network operations), "ai-data" (BSS/OSS AI monetisation, data platforms), "composable-it" (cloud-native IT, Open APIs, B2B/API marketplaces, vendor lock-in), "business-assurance" (revenue assurance, fraud, margin pressure), "process-etom" (business process transformation, ERP/systems consolidation).

Return ONLY valid JSON, no markdown wrapper, matching this exact schema:
{
  "snapshot": "2-3 sentence market overview",
  "operators": [
    {
      "name": "Operator name",
      "type": "Telecom | Satellite | MVNO | Fixed/Broadband",
      "tier": "Tier 1",
      "ownership": "brief ownership structure",
      "painPoints": [ { "cat": "autonomous-networks", "text": "specific pain point, 1-2 sentences" } ]
    }
  ]
}`;

const systemPrompt = mode === 'expanded'
  ? `${basePersona}

For the given country, identify 3-6 real, currently-operating TIER 2 or TIER 3 challenger telecom operators, ALTERNATIVE NETWORK (altnet) fibre/cable broadband providers, and/or satellite/LEO operators — explicitly NOT the country's dominant Tier 1 incumbent(s), which have already been covered separately. Aim for coverage across these categories where real operators exist, not just one. Tag each operator's "tier" field with exactly one of: "Tier 2", "Tier 3", "Altnet", "Satellite" — whichever best fits.

For each, give 1-3 genuine, specific pain points grounded in real industry themes as of 2025-2026 (e.g. wholesale scaling pressure, funding/consolidation risk, network build pace, OSS/BSS immaturity as a fast-growing challenger, spectrum/licensing constraints) — not generic filler. Leave the snapshot field as an empty string; only the operators list matters for this scan.

${schemaBlock}

If you have very limited or no reliable knowledge of Tier 2/3, altnet or satellite operators in this specific market, return an empty operators array rather than inventing details or substituting the incumbent.`
  : `${basePersona}

For the given country, provide:
1. A market snapshot: 2-3 sentences covering the competitive landscape, notable regulatory themes (spectrum policy, SATCOM licensing, open-access fibre mandates), and any current transformation momentum — grounded in real 2025-2026 developments, not generic filler.
2. Identify 2-4 real, currently-operating TIER 1 incumbent/dominant national telecom operators (use your actual knowledge of this market). Tag each operator's "tier" field as "Tier 1". For each, give 1-3 genuine, specific pain points grounded in real industry themes for that operator as of 2025-2026 — not generic filler.

${schemaBlock}

If you have very limited or no reliable knowledge of this market, return an empty string for snapshot and an empty operators array rather than inventing details.`;

const claudeBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 3000,
  system: systemPrompt,
  messages: [{ role: 'user', content: `Country: ${country}${region ? ' (' + region + ')' : ''}\n\nReturn the JSON market scan.` }]
};

return [{ json: { country, claudeBody } }];

const item = $input.first().json;
const country = $('Build Prompt').first().json.country;

if (item.error) {
  return [{ json: { success: false, error: 'Claude API error: ' + (item.error.message || JSON.stringify(item.error)) } }];
}

const raw = (item.content || []).find(c => c.type === 'text')?.text || '';
if (!raw) {
  return [{ json: { success: false, error: 'Empty response — please try again.' } }];
}

let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  return [{ json: { success: false, error: 'Could not parse market scan output. Raw: ' + raw.slice(0, 200) } }];
}

const validCats = ['autonomous-networks', 'ai-data', 'composable-it', 'business-assurance', 'process-etom'];
const validTiers = ['Tier 1', 'Tier 2', 'Tier 3', 'Altnet', 'Satellite'];
const operators = (parsed.operators || []).map(op => ({
  name: op.name || 'Unknown operator',
  type: op.type || 'Telecom',
  tier: validTiers.includes(op.tier) ? op.tier : 'Tier 2',
  ownership: op.ownership || '',
  painPoints: (op.painPoints || []).filter(pp => pp && pp.text).map(pp => ({
    cat: validCats.includes(pp.cat) ? pp.cat : 'composable-it',
    text: pp.text
  }))
})).filter(op => op.painPoints.length > 0);

const snapshot = typeof parsed.snapshot === 'string' ? parsed.snapshot : '';

return [{ json: { success: true, country, snapshot, operators } }];
